INSERT INTO `services` (`id`, `ids`, `uid`, `cate_id`, `name`, `desc`, `price`, `original_price`, `min`, `max`, `add_type`, `type`, `api_service_id`, `api_provider_id`, `dripfeed`, `status`, `changed`, `created`) VALUES
(1, 'c0495d4112e0e3ab3c512e5dc7d40b7b', 39, 29, 'Order tips for users', '✇ Order Tips 1: If you want fast services, Suggest testing day speed at a minimum first, and once that Instant suits you, then use that service for the time being. (Suggest per time is the best day-speed, not recommended to place the highest maximum amount, as it will stick) This will be better for your order on speed. *Speed = Amount / Start time = Progress time* NOTE: Followers add speed depending on the server and or profile account, it handles by the official update, and it can be sometimes slow or fast. It will not allow you to add too much as it is against the spy amount on the profile.\n\n\n✇ Order Tips 2: If you or your client\'s post/account to add the maximum and due issue, please use the other higher amount service (suggest per time), if the order is due to partial refund & cancel that means your same account or post cannot use that service anymore. It gives out the same followers or likes. In this case please order the other ID services.\n\n✇ Order Tips 3: For orders, issue problems usually take up 24-48HR automatically solve the problem. If the status is Partially completed/Canceled it means the system can\'t give more likes/followers to the current page/post and money will be automatically refunded for the remaining likes/followers. Please order on a different ID service in this case.\n\n\n✇ Order Tips 4: Some orders are due completed but not delivered, please file a new ticket to us with your order number, and we will check the issue request to service providers for you and give you speed up / refill/refund. Completed but count wrong due to reason: it runs on different services on followers at the same time will cause completed the wrong result / unfollow / or dropped the old LQ followers.\n\n\n✇ Order Tips 5: The drop followers problem is about what service the user selects, if a social media platform has a big update, or the user adds on the cheapest low-quality followers, will drop by the social media platform updated, if you want to prevent this happening, ple', 20000000000.0000, 10000000000.0000, 1000, 100000, 'api', 'default', '2216', 4, 0, 0, '2025-09-26 22:36:50', '2025-09-26 22:36:50'),
(2, '5f7f1e29542a309a2a32bdaf48188ecc', 39, 30, 'Send Us A Message On Whatsapp To Exchange Your Paypal For Momo', '', 2000.0000, 1000.0000, 1, 1, 'api', 'package', '6089', 4, 0, 1, '2025-09-26 22:36:50', '2025-09-26 22:36:50'),
(3, 'c63f36ca7fbedb039d833984cca9e2c0', 39, 31, 'CapCut Pro (Monthly – Private)', 'original subscription on your Mail or Private mail will be given\r\nYou can use on any device ( Computer, android, ios )\r\nput your gmail in the link box\r\nplace order and send order id to our whatsapp', 7.4000, 3.7000, 1000, 1000, 'api', 'package', '6448', 4, 0, 1, '2025-09-26 22:36:50', '2025-09-26 22:36:50'),
(4, 'bfc2a82892099dda87913ffc97016ba8', 39, 31, 'Amazon Prime Video [ 3 months ]', 'watch unlimited movies\nsupport ios, Android, Pc, Smart TV\nenter your whatsapp or gmail id  in  link section\nafter placing the order, send us order id via whatsapp for id & password\nprice for 90days', 19.0000, 9.5000, 1, 1, 'api', 'package', '3599', 4, 0, 1, '2025-09-26 22:36:50', '2025-09-26 22:36:50'),
(5, '5434e6fd097230c5e32b817e3dbf1a98', 39, 31, 'Apple Music Subscription 2months', '2 months apple music subscription \r\nput number or username in the link box\r\nContact Whatsapp support with the order id after placing the order', 11.0800, 5.5400, 1000, 1000, 'api', 'package', '6449', 4, 0, 1, '2025-09-26 22:36:50', '2025-09-26 22:36:50'),
(6, 'c9c40e4539ebc6392914312879a9a1b6', 39, 31, 'Apple Music Subscription 3months', '3 months apple music subscription\r\nput number or username in the link box\r\nContact Whatsapp support with the order id after placing the order', 14.6600, 7.3300, 1, 1, 'api', 'package', '5954', 4, 0, 1, '2025-09-26 22:36:50', '2025-09-26 22:36:50'),
(7, 'b9ab335fe381c342213d814c9c60d038', 39, 31, 'Apple Music Subscription 4months', '4months apple music subscription \r\nput number or username in the link box\r\nContact Whatsapp support with the order id after placing the order', 22.0000, 11.0000, 1, 1, 'api', 'package', '3181', 4, 0, 1, '2025-09-26 22:36:50', '2025-09-26 22:36:50'),
(8, 'c2a440d628992c0df2d6047aa1d792cf', 39, 31, 'Netflix Account - 4K Ultra HD | Shared [ 1 month ]', 'Send order id to us on whatsapp after placing the order.\nPut your username or number in the link box', 6.6000, 3.3000, 1, 1, 'api', 'package', '2264', 4, 0, 1, '2025-09-26 22:36:50', '2025-09-26 22:36:50'),
(9, 'e719ffa6ab4f58604619a0c6be744f2c', 39, 31, 'Netflix Account - 4K Ultra HD | Shared [ 3 months ]', '3 months premium netflix package \r\n\r\nSend order id to us on whatsapp after placing the order.\r\nPut your username or number in the link box\r\n\r\n\r\n# Instructions:........\r\nSingle user only \r\nDon\'t try to change password, username or anything in the account.\r\nJust use it in one device Coz this is one screen.\r\nIf you will use more than 1 device, we will block you and you will not be able to get your access and payment back.\r\n\r\nif any issue, dont try fixing it yourself. just inform us on whatsapp.\r\nenjoy!!', 18.0000, 9.0000, 1, 1, 'api', 'package', '5075', 4, 0, 1, '2025-09-26 22:36:50', '2025-09-26 22:36:50'),
(10, 'a4dd03bcb6a60b776e745a4897328cd3', 39, 31, 'Netflix Account - 4K Ultra HD | Shared [ 6 months ]', '', 32.0000, 16.0000, 1, 1, 'api', 'package', '5267', 4, 0, 1, '2025-09-26 22:36:50', '2025-09-26 22:36:50'),
